function tolerated(n){return Math.floor((n-1)/2);}
function majority(n){return Math.floor(n/2)+1;}
function survives(n,down){return (n-down)>=majority(n);}
const sizes=[1,3,4,5,7];
const lines=[];
for(const n of sizes){
  const f=tolerated(n);
  lines.push('n='+n+' majority='+majority(n)+' tolerates f='+f);
}
lines.push('---');
const checks=[[5,2],[5,3],[4,2],[3,1],[3,2],[7,3]];
for(const [n,down] of checks){
  lines.push('n='+n+' down='+down+' -> '+(survives(n,down)?'COMMITS (majority alive)':'HALTS (no majority)'));
}
console.log(lines.join('\n'));
